<script>(function(){var r=document.querySelector('.pr');if(!r||r.getAttribute('data-ok'))return;r.setAttribute('data-ok','1');r.classList.add('pr-js');
var tabs=r.querySelectorAll('.pr-tabs a'),ps=r.querySelectorAll('.pr-sec');
function show(id,scroll){var ok=false;ps.forEach(function(p){var on=p.getAttribute('data-p')===id;p.hidden=!on;if(on)ok=true});if(!ok)return false;tabs.forEach(function(t){t.setAttribute('aria-selected',t.getAttribute('data-t')===id?'true':'false')});
if(scroll){var n=r.querySelector('.pr-tabs');var y=n.getBoundingClientRect().top+window.pageYOffset-90;if(window.pageYOffset>y)window.scrollTo({top:y,behavior:'smooth'})}return true}
tabs.forEach(function(t){t.addEventListener('click',function(e){e.preventDefault();var id=t.getAttribute('data-t');show(id,true);try{history.replaceState(null,'','#pr-'+id)}catch(x){}})});
r.querySelectorAll('.pr-sw button').forEach(function(b){b.addEventListener('click',function(){var s=b.closest('.pr-sec');s.setAttribute('data-c',b.getAttribute('data-c'));s.querySelectorAll('.pr-sw button').forEach(function(x){x.setAttribute('aria-pressed',x===b?'true':'false')})})});
var h=(location.hash||'').replace('#pr-','');if(!h||!show(h,false))show('mixing',false);else setTimeout(function(){var n=r.querySelector('.pr-tabs');window.scrollTo(0,n.getBoundingClientRect().top+window.pageYOffset-90)},50);
})();</script>
